WRAPPERS=('func_1513EDB4','func_1513EDE4')

def header_states(live):
    old=['void '+n+'(s32 arg0, s16 arg1);'for n in WRAPPERS]
    new=['Vtx *'+n+'(u8 *actor, s16 view);'for n in WRAPPERS]
    if all(live.count(n)==1 for n in old):
        after=live
        for a,b in zip(old,new):after=after.replace(a,b,1)
        return live,after,False
    if not all(live.count(n)==1 for n in new):raise ValueError('Wrapper header changed')
    before=live
    for a,b in zip(old,new):before=before.replace(b,a,1)
    return before,live,True

def source_states(live,index=0):
    if index!=0:raise ValueError('One billboard quad')
    old='s32 func_1513EAD8(s32 arg0, s32 arg1, s32 arg2);';new='Vtx *func_1513EAD8(u8 *actor, u8 rotated, s16 view);'
    pairs=[]
    for name,variant in zip(WRAPPERS,(0,1)):
        a='void '+name+'(s32 arg0, s16 arg1) {\n    func_1513EAD8(arg0, '+str(variant)+', arg1);\n}'
        b='Vtx *'+name+'(u8 *actor, s16 view) {\n    return func_1513EAD8(actor, '+str(variant)+', view);\n}'
        pairs.append((a,b))
    if live.count(STUB)==1 and live.count(old)==1 and all(live.count(a)==1 for a,b in pairs):
        after=live.replace(STUB,SELECTED,1).replace(old,new,1)
        for a,b in pairs:after=after.replace(a,b,1)
        return live,after,False
    if live.count(SELECTED)!=1 or live.count(new)!=1 or not all(live.count(b)==1 for a,b in pairs):raise ValueError('Billboard source changed')
    before=live.replace(SELECTED,STUB,1).replace(new,old,1)
    for a,b in pairs:before=before.replace(b,a,1)
    return before,live,True

def compile_owner(root,out,source,name,flags=('-O2','-g3')):
    before,after,_=header_states((root/HEADER).read_text(encoding='utf-8'))
    header=out/(name+'-functions.h');header.write_text(after if SELECTED in source else before,encoding='utf-8')
    include=header.relative_to(root/'conker').as_posix()
    if source.count('#include "functions.h"')!=1:raise ValueError('Billboard include site changed')
    return _compile_owner(root,out,source.replace('#include "functions.h"','#include "'+include+'"',1),name,flags)
